#!/usr/bin/env python3
"""Generate the Oxford Trip v2 PWA app HTML.
Run this script to overwrite C:\paris\index.html with the complete Oxford Trip v2 app."""
import base64
import os

HTML_B64 = ""

def main():
    html = base64.b64decode(HTML_B64).decode('utf-8')
    outpath = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'index.html')
    with open(outpath, 'w', encoding='utf-8') as f:
        f.write(html)
    print(f"Written {len(html)} chars to {outpath}")

if __name__ == '__main__':
    main()